const octopusIcon=()=>`<svg class="octopus-icon" viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M15 26C7 29 3 24 5 20M17 29C9 39 2 33 5 29M20 31C17 44 8 42 10 36M23 32C23 44 17 46 17 40M25 32C25 44 31 46 31 40M28 31C31 44 40 42 38 36M31 29C39 39 46 33 43 29M33 26C41 29 45 24 43 20" stroke="currentColor" stroke-width="3.4" stroke-linecap="round"/><path d="M12 18C12 8 17 3 24 3S36 8 36 18C36 28 31 33 24 33S12 28 12 18Z" fill="currentColor"/><ellipse cx="19.5" cy="20" rx="2.3" ry="3" fill="#F5F8FF"/><ellipse cx="28.5" cy="20" rx="2.3" ry="3" fill="#F5F8FF"/><circle cx="20" cy="20.5" r="1" fill="#0B2D5B"/><circle cx="28" cy="20.5" r="1" fill="#0B2D5B"/><path d="M21.5 26Q24 28 26.5 26" stroke="#F5F8FF" stroke-width="1.5" stroke-linecap="round"/></svg>`;
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',inbox:'M4 4h16v16H4z M4 13h5l2 3h2l2-3h5',camera:'M3 7h4l2-3h6l2 3h4v14H3z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',flow:'M9 3h6v6H9z M3 16h6v5H3z M15 16h6v5h-6z M12 9v4M6 16v-3h12v3',chart:'M4 3v18h17 M8 16v-5m5 5V6m5 10v-7',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 3a4 4 0 0 1 0 8m2 4a4 4 0 0 1 3 4v2',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',plus:'M12 5v14M5 12h14',calendar:'M4 5h16v16H4z M4 10h16M8 3v4m8-4v4'};
const icon=n=>n==='spark'||n==='octopus'?octopusIcon():`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.home}"/></svg>`;
const pages=[['dashboard','اتاق فرمان','home'],['inbox','صندوق ورودی','inbox'],['studio','استودیو محتوا','camera'],['automations','خودکارسازی','flow'],['analytics','تحلیل و رشد','chart'],['audience','مخاطبان','users']];let current='dashboard',period='week';const main=document.querySelector('#main');
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let posts=[{title:'یک شروع تازه، یک ایده متفاوت',kind:'پست تصویری',time:'امروز، ۱۸:۳۰',draft:false},{title:'پشت صحنه روزهای پر از ایده',kind:'ریلز',time:'فردا، ۱۲:۰۰',draft:false},{title:'داستان برند ما از اینجا شروع شد',kind:'استوری',time:'بدون زمان',draft:true}];
const nav=document.querySelector('#nav');nav.innerHTML=pages.map(([id,label,ic])=>`<button class="nav-item" data-page="${id}">${icon(ic)}<span>${label}</span>${id==='inbox'?'<span class="badge">۱۲</span>':''}</button>`).join('');
document.querySelector('#date').textContent=new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'long',year:'numeric'}).format(new Date());
function heading(title,sub,action=true){return `<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions"><button class="btn" id="account">◎ <span dir="ltr">hashtiva.studio</span> ⌄</button>${action?`<button class="btn primary" data-action="post">${icon('plus')}ساخت محتوای جدید</button>`:''}</div></div>`}
function stats(){let values=period==='week'?['۲۴٬۸۵۰','۸۹٬۴۲۰','۶٫۸٪','۱٬۲۸۴']:['۲۶٬۳۲۰','۳۴۸٬۲۰۰','۷٫۲٪','۵٬۶۸۰'];return `<div class="stats">${[['دنبال‌کنندگان',values[0],'۱۲٫۸٪','users'],['بازدید محتوا',values[1],'۲۴٫۶٪','eye'],['نرخ تعامل',values[2],'۳٫۲٪','heart'],['پاسخ‌های خودکار',values[3],'۱۸٫۵٪','flow']].map(x=>`<article class="stat"><div class="stat-top"><span>${x[0]}</span><span class="stat-icon">${icon(x[3])}</span></div><div class="stat-value">${x[1]}</div><div class="stat-bottom"><span class="up">↗ ${x[2]}</span><span>نسبت به دوره قبل</span></div></article>`).join('')}</div>`}
function chart(){return `<section class="card"><div class="card-title"><h2>مسیر رشد شما</h2><div class="tabs"><button data-period="week" class="${period==='week'?'selected':''}">این هفته</button><button data-period="month" class="${period==='month'?'selected':''}">این ماه</button></div></div><div class="chart-sub">هر تعامل، یک فرصت تازه برای رشد</div><div class="chart-legend"><span><i class="dot"></i>بازدید محتوا</span><span><i class="dot cyan"></i>تعامل مخاطبان</span></div><svg class="chart" viewBox="0 0 600 180" role="img" aria-label="نمودار نمونه روند رشد بازدید و تعامل"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#6A5ACD" stop-opacity=".16"/><stop offset="1" stop-color="#6A5ACD" stop-opacity="0"/></linearGradient></defs>${[20,60,100,140].map((y,i)=>`<line x1="10" y1="${y}" x2="550" y2="${y}"/><text x="595" y="${y+3}" text-anchor="end">${['۳۰ هزار','۲۰ هزار','۱۰ هزار','۰'][i]}</text>`).join('')}<path d="M10 125 C50 120 60 80 100 90 S160 126 190 97 S250 106 280 65 S340 90 370 57 S430 100 460 53 S510 60 550 ${period==='week'?22:9} L550 145H10Z" fill="url(#area)"/><path d="M10 125 C50 120 60 80 100 90 S160 126 190 97 S250 106 280 65 S340 90 370 57 S430 100 460 53 S510 60 550 ${period==='week'?22:9}" fill="none" stroke="#6A5ACD" stroke-width="3"/><path d="M10 139 C50 134 60 118 100 122 S160 131 190 119 S250 125 280 103 S340 116 370 93 S430 115 460 90 S510 98 550 71" fill="none" stroke="#14B8A6" stroke-width="2" stroke-dasharray="5 5"/>${['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'].map((t,i)=>`<text x="${i*85+15}" y="175" text-anchor="middle">${t}</text>`).join('')}</svg><div class="chart-foot"><span>روند عملکرد در ${period==='week'?'۷':'۳۰'} روز گذشته</span><span style="color:#18a58d">↗ عملکرد بهتر از دوره قبل</span></div></section>`}
function priority(){return `<section class="card"><div class="card-title"><h2>قدم بعدی شما</h2><span class="badge">۳ پیشنهاد</span></div><div class="chart-sub">روی کارهایی تمرکز کنید که مهم‌اند</div>${[['inbox','۱۲ گفتگو منتظر پاسخ شماست','یک پاسخ به‌موقع، شروع یک رابطه ماندگار.','مشاهده پیام‌ها','inbox'],['clock','بهترین زمان انتشار، ساعت ۱۸ تا ۲۱','امروز مخاطبان شما در این ساعت فعال‌ترند.','برنامه‌ریزی محتوا','studio'],['flow','به استقبال مخاطبان تازه بروید','پیام خوشامدگویی خودکار را فعال کنید.','تنظیم خودکارسازی','automations']].map(x=>`<div class="priority-row"><span class="priority-icon">${icon(x[0])}</span><div><b>${x[1]}</b><p>${x[2]}</p><button data-page="${x[4]}">${x[3]} ←</button></div></div>`).join('')}</section>`}
function postRows(){return posts.map((p,i)=>`<div class="schedule-row"><div class="thumb ${i%2?'warm':''}">${icon(i%2?'camera':'chart')}</div><div><b>${safe(p.title)}</b><small>${p.kind} · اینستاگرام</small></div><span class="status ${p.draft?'draft':''}">${p.draft?'پیش‌نویس':'زمان‌بندی شده'}</span><time>${safe(p.time)}</time></div>`).join('')}
function dashboard(){return heading('یک روز تازه، یک فرصت تازه ✦','نمایی روشن از کسب‌وکار شما؛ همه چیز تحت کنترل است.')+`<section class="hero"><div><span class="eyebrow">✧ دستیار هوشمند هشتیوا <span style="opacity:.4">/</span> گزارش امروز</span><h2>شما روی ایده‌ها تمرکز کنید، باقی با هشتیوا.</h2><p>تعامل صفحه‌تان این هفته <span style="color:#64e1e1">۲۴٪ رشد کرده</span>؛ محتوای شما بیشتر دیده می‌شود.<br>امروز ۳ محتوا در صف انتشار دارید و دستیار شما پاسخ‌گوی مخاطبان است.</p><button class="hero-link" data-page="analytics">نگاهی دقیق‌تر به عملکرد شما <span>←</span></button></div><div class="hero-symbol" aria-hidden="true">✧</div></section><div class="section-label"><h2>نبض کسب‌وکار</h2><small>داده‌های نمونه · ۷ روز گذشته</small></div><div id="stats">${stats()}</div><div class="chart-grid"><div id="chartwrap">${chart()}</div>${priority()}</div><div class="bottom-grid"><section class="card"><div class="card-title"><h2>محتوای بعدی شما</h2><button class="text-link" data-page="studio">مشاهده استودیو ←</button></div>${postRows()}</section><section class="card"><div class="card-title"><h2>دستیار شما در حال کار است</h2><span class="status">فعال</span></div><div class="chart-sub">زمان شما، برای کارهای ارزشمندتر</div><div class="mini-metric"><div class="ring"></div><div><b>۸۶٪ پاسخ‌گویی خودکار</b><p><i class="dot"></i>۱٬۲۸۴ پاسخ هوشمند</p><p><i class="dot cyan"></i>۳٫۵ ساعت صرفه‌جویی</p></div></div><div class="mini-note">✧ هیچ فرصتی برای گفتگو از دست نمی‌رود.</div></section></div>`}
let chat=0;const contacts=['سارا محمدی','آرمان رضایی','نگار احمدی'];const messages=['سلام، برای شروع استفاده از خدماتتون از کجا اقدام کنم؟','سلام وقت بخیر، درباره قیمت‌ها راهنمایی می‌کنید؟','ممنون از محتوای خوبتون! امکان همکاری هست؟'];let replies=[[],[],[]];
function inbox(){return heading('صندوق ورودی','همه گفتگوها، در یک فضای منظم و ساده.',false)+`<div class="inbox-layout"><div class="card"><h2>گفتگوهای اخیر</h2>${contacts.map((n,i)=>`<button class="conversation ${i===chat?'selected':''}" data-chat="${i}"><b>${n}</b><small>${messages[i]}</small></button>`).join('')}</div><section class="card"><div class="card-title"><h2>${contacts[chat]}</h2><small>اینستاگرام · گفتگوی نمونه</small></div><div class="bubble">${messages[chat]}</div>${replies[chat].map(t=>`<div class="bubble reply">${safe(t)}</div>`).join('')}<form class="reply-form" id="reply-form"><input name="reply" aria-label="متن پاسخ" placeholder="پاسخ خود را بنویسید…" required><button class="btn primary">ارسال نمایشی</button></form></section></div>`}
function render(page='dashboard'){current=page;const title=pages.find(p=>p[0]===page)?.[1]||{settings:'تنظیمات',help:'راهنما و پشتیبانی',plans:'اشتراک‌ها'}[page];document.querySelector('#crumb').textContent=title;document.title=`هشتیوا | ${title}`;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelector('#sidebar').classList.remove('open');if(page==='dashboard')main.innerHTML=dashboard();else if(page==='inbox')main.innerHTML=inbox();else if(page==='analytics')main.innerHTML=heading('تحلیل و رشد','تصویر دقیق‌تر از آنچه برای مخاطبان شما ارزشمند است.',false)+`<div id="stats">${stats()}</div><div class="chart-grid"><div id="chartwrap">${chart()}</div>${priority()}</div>`;else if(page==='studio')main.innerHTML=heading('استودیو محتوا','از اولین ایده تا لحظه انتشار؛ داستان برندتان را بسازید.')+`<section class="card"><div class="card-title"><h2>برنامه انتشار</h2><span class="badge">${posts.length.toLocaleString('fa-IR')} محتوا</span></div>${postRows()}</section>`;else if(page==='automations')main.innerHTML=heading('خودکارسازی','مکالمه‌های بهتر، حتی وقتی مشغول کارهای مهم‌ترید.',false)+`<div class="page-grid">${[['پاسخ خودکار دایرکت','به سؤال‌های پرتکرار مخاطبان، سریع و دقیق پاسخ دهید.'],['پیام خوشامدگویی','اولین ارتباط با مخاطبان تازه را به‌یادماندنی کنید.'],['مدیریت کامنت‌ها','گفتگو را از زیر پست‌ها به یک ارتباط سازنده تبدیل کنید.'],['پیگیری هوشمند','گفتگوهای ناتمام را با یک پیام مناسب ادامه دهید.'],['محافظ کامنت','فضایی سالم و سازنده برای تعامل مخاطبان بسازید.'],['دریافت اطلاعات مخاطب','فرصت‌های ارتباط با مشتری را در یک مسیر ساده جمع کنید.']].map((x,i)=>`<section class="card"><div class="card-title"><span class="stat-icon">${icon('flow')}</span><button class="toggle ${i%2?'':'on'}" role="switch" aria-checked="${!(i%2)}" aria-label="${x[0]}"></button></div><h3>${x[0]}</h3><p>${x[1]}</p><small>تنظیمات نمایشی · بدون اتصال به اینستاگرام</small></section>`).join('')}</div>`;else if(page==='audience')main.innerHTML=heading('مخاطبان','پشت هر عدد، یک فرصت برای ارتباط بهتر وجود دارد.',false)+`<div class="card"><div class="card-title"><h2>فهرست مخاطبان نمونه</h2></div><input id="audience-search" placeholder="جستجوی نام مخاطب…" aria-label="جستجوی مخاطبان"><div id="audience-list">${audienceRows('')}</div></div>`;else if(page==='settings')main.innerHTML=heading('تنظیمات فضای کار','فضای کاری‌تان را مطابق نیاز خود تنظیم کنید.',false)+`<form class="card" id="settings-form" style="max-width:650px"><h2>پروفایل کسب‌وکار</h2><label>نام کسب‌وکار</label><input name="business" value="${safe(localStorage.getItem('hashtiva-business')||'کسب‌وکار من')}" required><label>معرفی کوتاه برند</label><textarea name="bio" placeholder="درباره کسب‌وکارتان بنویسید…">${safe(localStorage.getItem('hashtiva-bio')||'')}</textarea><p><button class="btn primary">ذخیره در این مرورگر</button></p><small>این تنظیمات فقط برای پیش‌نمایش رابط کاربری ذخیره می‌شوند.</small></form>`;else if(page==='plans')main.innerHTML=heading('همراه رشد کسب‌وکار شما','نمایش ساختار اشتراک‌ها؛ خرید در این نسخه فعال نیست.',false)+`<div class="page-grid">${['شروع','رشد','حرفه‌ای'].map((t,i)=>`<section class="card"><span class="stat-icon" style="width:35px">${icon('chart')}</span><h3>${t}</h3><p>${['برای قدم‌های اول در مدیریت محتوا','برای کسب‌وکارهای در حال توسعه','برای تیم‌ها و مدیریت چند صفحه'][i]}</p><p>برنامه‌ریزی محتوا<br>صندوق ورودی یکپارچه<br>گزارش عملکرد</p><small>جزئیات قیمت پس از اتصال به سرویس اشتراک</small></section>`).join('')}</div>`;else main.innerHTML=heading('همیشه کنارتان هستیم','راهنمای شروع کار با هشتیوا',false)+`<section class="card">${[['این نسخه به اینستاگرام متصل است؟','خیر. این سایت پیش‌نمایش طراحی است و تمام آمار، پیام‌ها و محتوا نمونه‌اند.'],['از کجا شروع کنم؟','در اتاق فرمان نمای کلی را ببینید؛ در استودیو یک محتوای نمایشی بسازید و زمان انتشارش را تنظیم کنید.'],['چطور پیام‌ها را مدیریت کنم؟','از صندوق ورودی گفتگو را انتخاب کنید و پاسخ نمایشی بنویسید. هیچ پیامی به بیرون ارسال نمی‌شود.']].map(x=>`<details style="padding:20px;border-bottom:1px solid var(--border)"><summary style="cursor:pointer">${x[0]}</summary><p style="color:var(--muted)">${x[1]}</p></details>`).join('')}</section>`;}
function audienceRows(q){return contacts.filter(n=>n.includes(q)).map((n,i)=>`<div class="schedule-row"><span class="avatar">${n[0]}</span><div><b>${n}</b><small>آخرین تعامل: امروز</small></div><span class="status">${i?'مخاطب فعال':'مشتری جدید'}</span></div>`).join('')||'<p class="empty">مخاطبی با این نام پیدا نشد.</p>'}
const dialog=document.querySelector('#dialog');function modal(html){document.querySelector('#dialog-content').innerHTML=html;dialog.showModal()}function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',3500)}
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){location.hash=page.dataset.page;return}if(e.target.closest('.close'))dialog.close();if(e.target.closest('[data-action="post"]'))modal(`<h2>یک ایده تازه بسازید</h2><small>محتوای نمایشی؛ در اینستاگرام منتشر نمی‌شود.</small><form id="post-form"><label>عنوان محتوا</label><input name="title" required placeholder="ایده امروز شما چیست؟" maxlength="90"><label>نوع محتوا</label><select name="kind"><option>پست تصویری</option><option>ریلز</option><option>استوری</option></select><label>زمان انتشار (اختیاری)</label><input name="time" type="datetime-local"><label>متن محتوا</label><textarea name="caption" placeholder="داستانتان را بنویسید…"></textarea><p><button class="btn primary">افزودن به استودیو</button></p></form>`);const p=e.target.closest('[data-period]');if(p){period=p.dataset.period;document.querySelector('#stats').innerHTML=stats();document.querySelector('#chartwrap').innerHTML=chart()}const ch=e.target.closest('[data-chat]');if(ch){chat=+ch.dataset.chat;render('inbox')}const toggle=e.target.closest('.toggle');if(toggle){toggle.classList.toggle('on');toggle.setAttribute('aria-checked',toggle.classList.contains('on'));toast('وضعیت نمایشی تغییر کرد')}if(e.target.closest('#account'))modal('<h2>حساب اینستاگرام</h2><div class="workspace"><span class="avatar">ه</span><div><b dir="ltr">hashtiva.studio</b><small>حساب نمونه برای نمایش طراحی</small></div></div><p>اتصال حساب واقعی در این نسخه فعال نیست.</p>')});
document.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.id==='post-form'){const date=f.get('time');posts.unshift({title:f.get('title'),kind:f.get('kind'),time:date?new Intl.DateTimeFormat('fa-IR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(date)):'بدون زمان',draft:!date});dialog.close();location.hash='studio';render('studio');toast('محتوای نمونه به استودیو اضافه شد')}if(e.target.id==='reply-form'){const t=f.get('reply').trim();if(t){replies[chat].push(t);render('inbox');toast('پاسخ نمایشی ثبت شد؛ پیامی ارسال نشد')}}if(e.target.id==='settings-form'){localStorage.setItem('hashtiva-business',f.get('business'));localStorage.setItem('hashtiva-bio',f.get('bio'));document.querySelector('.workspace b').textContent=f.get('business');toast('تنظیمات در این مرورگر ذخیره شد')}});
document.addEventListener('input',e=>{if(e.target.id==='audience-search')document.querySelector('#audience-list').innerHTML=audienceRows(e.target.value)});document.querySelector('#menu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('hashtiva-theme',document.body.classList.contains('dark')?'dark':'light')};if(localStorage.getItem('hashtiva-theme')==='dark')document.body.classList.add('dark');document.querySelector('#notifications').onclick=()=>modal('<h2>اعلان‌های شما</h2><div class="priority-row"><span>✧</span><div><b>به هشتیوا خوش آمدید</b><p>این فضای نمایشی برای بررسی طراحی آماده شده است.</p></div></div><small>اعلان جدید دیگری ندارید.</small>');window.addEventListener('hashchange',()=>{render(location.hash.slice(1)||'dashboard');window.scrollTo(0,0)});render(location.hash.slice(1)||'dashboard');
